define({"topics":[{"title":"Checking the bridge cover vertical alignment","shortdesc":"<p class=\"shortdesc\">Makes sure the vertical alignment of the bridge cover is within acceptable limits. This procedure must be performed prior to checking the cradle home sensor position.<\/p>","href":"t_CheckingTheBridgeCoverAlignment.html","attributes":{"data-id":"id_2002574"},"menu":{"hasChildren":false},"tocID":"id_2002574-d46e69195","topics":[]},{"title":"Adjusting the bridge cover vertical alignment","shortdesc":"<p class=\"shortdesc\">Adjusts the vertical alignment of the bridge cover. Do this procedure when the bridge cover vertical alignment is not within acceptable tolerances.<\/p>","href":"t_AdjustingTheBridgeCoverVerticalAlignment.html","attributes":{"data-id":"id_2003358"},"menu":{"hasChildren":true},"tocID":"id_2003358-d46e69299","next":"id_2003358-d46e69299"}]});